def transform(grid):
    # Keep only the boundary rows of contiguous horizontal blocks/bands
    res = [row[:] for row in grid]
    R = len(grid)
    for r in range(R):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                # interior row if top and bottom are also non-zero
                if r > 0 and r < R - 1 and grid[r-1][c] != 0 and grid[r+1][c] != 0:
                    res[r][c] = 0
    return res

def transform(grid):
    # For any 3 consecutive non-zero rows, zero the middle one
    res = [row[:] for row in grid]
    R = len(grid)
    for r in range(1, R - 1):
        if any(grid[r-1]) and any(grid[r]) and any(grid[r+1]):
            res[r] = [0] * len(grid[0])
    return res
